// Regenerates src/index.ts from the ts-rs output in src/generated.
import { readdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const gen = join(here, "..", "src", "generated");
const names = readdirSync(gen)
  .filter((f) => f.endsWith(".ts"))
  .map((f) => f.slice(0, -3))
  .sort();
const lines = [
  "// Generated by scripts/gen-index.mjs from the Rust types (ts-rs). Do not edit.",
  ...names.map((n) => `export type { ${n} } from "./generated/${n}";`),
  'export type { JsonValue } from "./generated/serde_json/JsonValue";',
  "",
];
writeFileSync(join(here, "..", "src", "index.ts"), lines.join("\n"));
console.log(`index.ts: ${names.length} types`);
